func main() {
    for _, e := range []syscall.Errno{101,111,97,110,113,99,22} {
        fmt.Printf("%d => %q\n", int(e), e.Error())
    }
    // Test DNS lookup errors
    for _, host := range []string{"nonexistent.invalid", "example.com", "256.256.256.256", "", "[::1]", "localhost:bad"} {
        fmt.Printf("--- Lookup %q ---\n", host)
        _, err := net.LookupHost(host)
        if err != nil {
            fmt.Printf("err type %T: %v\n", err, err)
            if dnsErr, ok := err.(*net.DNSError); ok {
                fmt.Printf("DNS: Err=%q IsNotFound=%v IsTemporary=%v\n", dnsErr.Err, dnsErr.IsNotFound, dnsErr.IsTemporary)
            }
        } else {
            fmt.Printf("ok\n")
        }
    }
    // Test dial errors
    for _, addr := range []string{"127.0.0.1:1", "10.0.0.2:53", "[::1]:53", "1.1.1.1:bad", "localhost:bad", ":53", "1.1.1.1:"} {
        fmt.Printf("--- Dial udp %q ---\n", addr)
        conn, err := net.Dial("udp", addr)
        if err != nil {
            fmt.Printf("err type %T: %v\n", err, err)
            if opErr, ok := err.(*net.OpError); ok {
                fmt.Printf("Op=%q Net=%q Addr=%v Err=%T %v\n", opErr.Op, opErr.Net, opErr.Addr, opErr.Err, opErr.Err)
                if sysErr, ok := opErr.Err.(*net.AddrError); ok {
                    fmt.Printf("AddrError: %q\n", sysErr.Err)
                }
                if sysErr, ok := opErr.Err.(*net.DNSError); ok {
                    fmt.Printf("DNSError: %q\n", sysErr.Err)
                }
                if sysErr, ok := opErr.Err.(*net.ParseError); ok {
                    fmt.Printf("ParseError: %q %q\n", sysErr.Type, sysErr.Text)
                }
                if errno, ok := opErr.Err.(syscall.Errno); ok {
                    fmt.Printf("Errno %d %q\n", int(errno), errno.Error())
                }
            }
        } else {
            conn.Close()
            fmt.Printf("ok\n")
        }
    }
}
