{"command":"cat > /tmp/cgotest.go <<'GO'
package main

/*
#include <netdb.h>
#include <sys/socket.h>
#include <string.h>
#include <stdio.h>
*/
import "C"
import (
    "fmt"
    "unsafe"
)

func test(host, port string) {
    chost := C.CString(host)
    cport := C.CString(port)
    defer C.free(unsafe.Pointer(chost))
    defer C.free(unsafe.Pointer(cport))
    var hints C.struct_addrinfo
    C.memset(unsafe.Pointer(&hints), 0, C.sizeof_struct_addrinfo)
    hints.ai_family = C.AF_UNSPEC
    hints.ai_socktype = C.SOCK_DGRAM
    var res *C.struct_addrinfo
    ret := C.getaddrinfo(chost, cport, &hints, &res)
    if ret != 0 {
        errStr := C.GoString(C.gai_strerror(ret))
        fmt.Printf("getaddrinfo(%q,%q) => %d %q\n", host, port, ret, errStr)
    } else {
        fmt.Printf("getaddrinfo(%q,%q) => OK\n", host, port)
        C.freeaddrinfo(res)
    }
}

func main() {
    test("example.com", "53")
    test("256.256.256.256", "53")
    test("::1", "53")
    test("::1", "")
    test("", "53")
    test("localhost", "53")
    test("localhost", "bad")
    test("1.1.1.1", "bad")
    test("1.1.1.1", "")
    test("[::1]", "53")
    test("example.com:443", "443")
}
GO
go run /tmp/cgotest.go 2>&1 | head -n 50
"}

