	"EUI64":      109,
	"TKEY":       249,
	"TSIG":       250,
	"IXFR":       251,
	"AXFR":       252,
	"URI":        256,
	"CAA":        257,
	"TA":         32768,
	"DLV":        32769,
	"ANY":        255,
}

var codeToTypeName = map[uint16]string{}

func init() {
	for k, v := range typeNameToCode {
		// For codes that map to multiple? No duplicates except? Keep first.
		if _, exists := codeToTypeName[v]; !exists {
			codeToTypeName[v] = k
		}
	}
}

// Interpreted types (have specific formatting, not bytes)
var interpretedTypes = map[uint16]bool{
	1:   true, // A
	28:  true, // AAAA
	257: true, // CAA
	5:   true, // CNAME
	13:  true, // HINFO
	29:  true, // LOC
	15:  true, // MX
	35:  true, // NAPTR
	2:   true, // NS
	41:  true, // OPT (but not queryable)
	12:  true, // PTR
	6:   true, // SOA
	33:  true, // SRV
	44:  true, // SSHFP
	52:  true, // TLSA
	16:  true, // TXT
	61:  true, // OPENPGPKEY
	108: true, // EUI48
	109: true, // EUI64
	256: true, // URI
}

func parseQueryType(s string) (uint16, string, bool, bool) {
	// Returns (code, name, isOPT, ok)
	// name is canonical uppercase name if known, else "" for unknown numeric
	// isOPT true if s is OPT (case-insensitive)
	if strings.EqualFold(s, "OPT") {
		return 41, "OPT", true, false
	}
	upper := strings.ToUpper(s)
	if code, ok := typeNameToCode[upper]; ok {
		return code, upper, false, true
	}
	// Try numeric with optional +?
	if code, ok := parseDecimalU16(s); ok {
		// Check if code maps to known name? For numeric, we still return name if known?
		// For display, numeric 1 should show as "A", not 1. So lookup.
		if name, exists := codeToTypeName[code]; exists {
			// But need to handle: numeric 41 (OPT) via -t 41? What happens? Test: -t 41 should be? OPT is 41, but -t OPT gives special error. What about -t 41? Let's see: numeric 41 might also give OPT error? Need to test.
			// For now, if code==41, treat as OPT error?
			if code == 41 {
				return 41, "OPT", true, false
			}
			return code, name, false, true
		}
		return code, "", false, true
	}
	return 0, "", false, false
}

func typeCodeToName(code uint16) (string, bool) {
	if name, ok := codeToTypeName[code]; ok {
		return name, true
	}
	// Check OPT?
	if code == 41 {
		return "OPT", true
	}
	return "", false
}

func isInterpreted(code uint16) bool {
	return interpretedTypes[code]
}

// Class mappings
var classNameToCode = map[string]uint16{
	"IN": 1,
	"CH": 3,
	"HS": 4,
}

var codeToClassName = map[uint16]string{
	1: "IN",
	3: "CH",
	4: "HS",
}

func parseQueryClass(s string) (uint16, string, bool) {
	upper := strings.ToUpper(s)
	if code, ok := classNameToCode[upper]; ok {
		return code, upper, true
	}
	if code, ok := parseDecimalU16(s); ok {
		if name, exists := codeToClassName[code]; exists {
			return code, name, true
		}
		return code, "", true
	}
	return 0, "", false
}

func classCodeToName(code uint16) (string, bool) {
	if name, ok := codeToClassName[code]; ok {
		return name, true
	}
	return "", false
}
