						return nil, fmt.Sprintf("dog: Invalid options: Option '%s' given more than once\n", "color"), false
					}
					opts.seenColor = true
					_ = val
				case "colour":
					if opts.seenColour {
						return nil, fmt.Sprintf("dog: Invalid options: Option '%s' given more than once\n", "colour"), false
					}
					opts.seenColour = true
					_ = val
				}
