					}
					opts.seenJSON = true
				case "seconds":
					if opts.seenSeconds {
						return nil, fmt.Sprintf("dog: Invalid options: Option '%s' given more than once\n", "seconds"), false
					}
					opts.seenSeconds = true
				case "time":
					if opts.seenTime {
						return nil, fmt.Sprintf("dog: Invalid options: Option '%s' given more than once\n", "time"), false
					}
					opts.seenTime = true
				case "help":
					if opts.seenHelp {
						return nil, fmt.Sprintf("dog: Invalid options: Option '%s' given more than once\n", "help"), false
					}
					opts.seenHelp = true
					opts.Help = true
				case "version":
					if opts.seenVersion {
						return nil, fmt.Sprintf("dog: Invalid options: Option '%s' given more than once\n", "version"), false
					}
					opts.seenVersion = true
					opts.Version = true
				}
				i++
				continue
			default:
				return nil, fmt.Sprintf("dog: Invalid options: Unrecognized option: '%s'\n", name), false
			}
		} else if strings.HasPrefix(arg, "-") && len(arg) > 1 {
			// short options, possibly combined
			j := 1
			for j < len(arg) {
				c := arg[j]
				switch c {
				case 'q', 't', 'n', 'Z':
					var val string
					if j+1 < len(arg) {
						val = arg[j+1:]
						// consume rest of current arg as value
						j = len(arg) // end loop for this arg
					} else {
						// need next arg
						if i+1 >= len(args) {
							return nil, fmt.Sprintf("dog: Invalid options: Argument to option '%c' missing\n", c), false
						}
						val = args[i+1]
						i++ // consume next
						j = len(arg)
					}
					// Store (no duplicate for q,t,n,Z)
					_ = val
					// For Z, need to handle? No duplicate check
					// Break inner loop (since value consumed rest)
					break
				case 'U', 'T', 'S', 'H', '1', 'J', 'v', '?':
					var canonical string
					switch c {
					case 'U':
						canonical = "udp"
						if opts.seenUDP {
