						}
						opts.seenUDP = true
					case 'T':
						canonical = "tcp"
						if opts.seenTCP {
							return nil, fmt.Sprintf("dog: Invalid options: Option '%s' given more than once\n", canonical), false
						}
						opts.seenTCP = true
					case 'S':
						canonical = "tls"
						if opts.seenTLS {
							return nil, fmt.Sprintf("dog: Invalid options: Option '%s' given more than once\n", canonical), false
						}
						opts.seenTLS = true
					case 'H':
						canonical = "https"
						if opts.seenHTTPS {
							return nil, fmt.Sprintf("dog: Invalid options: Option '%s' given more than once\n", canonical), false
						}
						opts.seenHTTPS = true
					case '1':
						canonical = "short"
						if opts.seenShort {
							return nil, fmt.Sprintf("dog: Invalid options: Option '%s' given more than once\n", canonical), false
						}
						opts.seenShort = true
					case 'J':
						canonical = "json"
						if opts.seenJSON {
							return nil, fmt.Sprintf("dog: Invalid options: Option '%s' given more than once\n", canonical), false
						}
						opts.seenJSON = true
					case 'v':
						canonical = "version"
						if opts.seenVersion {
							return nil, fmt.Sprintf("dog: Invalid options: Option '%s' given more than once\n", canonical), false
						}
						opts.seenVersion = true
						opts.Version = true
					case '?':
						canonical = "help"
						if opts.seenHelp {
							return nil, fmt.Sprintf("dog: Invalid options: Option '%s' given more than once\n", canonical), false
						}
						opts.seenHelp = true
						opts.Help = true
					}
					j++
					continue
				default:
					return nil, fmt.Sprintf("dog: Invalid options: Unrecognized option: '%c'\n", c), false
				}
				// For q,t,n,Z case, we already set j=len, need to break to outer? Actually we need to exit inner loop
				if c == 'q' || c == 't' || c == 'n' || c == 'Z' {
					break
				}
			}
			i++
			continue
		} else {
			positionals = append(positionals, arg)
			i++
			continue
		}
	}
	_ = positionals
	return opts, "", false
}
