package main

import (
	"encoding/binary"
	"fmt"
	"strings"
)

type Question struct {
	Name  string // with trailing dot or "" for root
	Class uint16
	Type  uint16
}

type Record struct {
	Name  string
	Class uint16
	TTL   uint32
	Type  uint16
	Data  interface{} // typed data
	Raw   []byte      // raw rdata for unknown types
}

type Response struct {
	Questions   []Question
	Answers     []Record
	Authorities []Record
	Additionals []Record // includes OPT if present (but filtered based on edns setting? Actually parsing includes OPT, filtering happens at display)
	Rcode       uint8
	TC          bool
}

// Build query packet
func buildQuery(labels []string, qtype, qclass uint16, txid uint16, edns string, tweaksAA, tweaksAD, tweaksCD bool, bufsize *uint16) []byte {
	var pkt []byte
	hdr := make([]byte, 12)
	binary.BigEndian.PutUint16(hdr[0:2], txid)
	flags := uint16(0x0100) // RD
	if tweaksAA {
		flags |= 0x0400 // AA
	}
	if tweaksAD {
		flags |= 0x0020 // AD
	}
	if tweaksCD {
		flags |= 0x0010 // CD
	}
	binary.BigEndian.PutUint16(hdr[2:4], flags)
	binary.BigEndian.PutUint16(hdr[4:6], 1) // QD
	binary.BigEndian.PutUint16(hdr[6:8], 0)
	binary.BigEndian.PutUint16(hdr[8:10], 0)
	if edns == "disable" {
		binary.BigEndian.PutUint16(hdr[10:12], 0)
	} else {
		binary.BigEndian.PutUint16(hdr[10:12], 1)
	}
	pkt = append(pkt, hdr...)
	pkt = append(pkt, domainToWire(labels)...)
	tmp := make([]byte, 4)
	binary.BigEndian.PutUint16(tmp[0:2], qtype)
	binary.BigEndian.PutUint16(tmp[2:4], qclass)
	pkt = append(pkt, tmp...)
