func formatLatLon(val uint32, isLat bool) (string, bool) {
	const base uint32 = 2147483648 // 2^31
	var maxMs uint32
	if isLat {
		maxMs = 90 * 3600000 // 324000000
	} else {
		maxMs = 180 * 3600000 // 648000000
	}
	var diff int64
	if val >= base {
		diff = int64(val - base)
	} else {
		diff = -int64(base - val)
	}
	// Check out of range: abs(diff) > maxMs ?
	if diff > int64(maxMs) || diff < -int64(maxMs) {
		return "", false
	}
	var hemi string
	var absDiff int64
	if isLat {
		if diff >= 0 {
			hemi = "N"
			absDiff = diff
		} else {
			hemi = "S"
			absDiff = -diff
		}
	} else {
		if diff >= 0 {
			hemi = "E"
			absDiff = diff
		} else {
			hemi = "W"
			absDiff = -diff
		}
	}
