	// CNAME,TXT,HINFO,TLSA,LOC,EUI48,URI: 33
	// EUI64: 1;33
	// NS,PTR,CAA,NAPTR: 31
	// MX,SRV,SSHFP,OPENPGPKEY: 36
	// SOA,OPT: 35
	// Unknown: 41;37
	switch code {
	case 1, 28:
		return "1;32"
	case 5, 16, 13, 52, 29, 108, 256:
		return "33"
	case 109:
		return "1;33"
	case 2, 12, 257, 35:
		return "31"
	case 15, 33, 44, 61:
		return "36"
	case 6, 41:
		return "35"
	default:
		return "41;37"
	}
}

