		}
		return nil, "network", err.Error()
	}
	ln := binary.BigEndian.Uint16(hdr)
	resp := make([]byte, ln)
	_, err = io.ReadFull(conn, resp)
	if err != nil {
		if errno, ok := extractErrno(err); ok {
			return nil, "network", formatOsError(errno)
		}
		return nil, "network", err.Error()
	}
	return resp, "", ""
}

// TLS query
func doTLSQuery(nameserver string, query []byte) ([]byte, string, string) {
	// Parse as: if contains ':', host=before first ':', portStr=after last ':', else host=nameserver, port=853
	var host, portStr string
	var port uint16
	if strings.Contains(nameserver, ":") {
		firstIdx := strings.Index(nameserver, ":")
		lastIdx := strings.LastIndex(nameserver, ":")
		host = nameserver[:firstIdx]
		portStr = nameserver[lastIdx+1:]
		p, kind := parsePortRust(portStr)
		if kind != "" {
			tlsPanic(kind)
		}
		port = p
		_ = port
	} else {
		host = nameserver
		portStr = "853"
		port = 853
	}
	_ = port
	// Resolve host via cgo (without stripping brackets, without IP check? For TLS, host with brackets like "[::1]" is passed as-is to getaddrinfo, which fails.)
	// For empty host, cgo with "" fails.
	// For valid IP without brackets, cgo succeeds (getaddrinfo with IP succeeds). For hostname, cgo does DNS.
	// Note: for TLS, host "[::1]" includes brackets, cgo fails. Good.
	// For host "::1"? Actually for "127.0.0.1:53", host="127.0.0.1", portStr="53", cgo with host "127.0.0.1", port "53" succeeds.
	addrs, errStr := cgoResolve(host, portStr, 0)
	if errStr != "" {
		return nil, "network", fmt.Sprintf("failed to lookup address information: %s", errStr)
	}
	var lastMsg string
	for _, addr := range addrs {
		resp, phase, msg := tlsDialAddr(addr, host, query)
