			return resp, "", ""
		}
		// If phase is "tls", return immediately? Or try next? For TLS handshake failure (e.g., cert verify), trying next addr won't help (same cert). But for network errors (e.g., connection refused on first addr), try next.
		// Rust's TLS connect probably tries each addr? For simplicity, if phase=="tls", return immediately, else try next and save last.
		if phase == "tls" {
			return nil, phase, msg
		}
		lastMsg = msg
	}
	return nil, "network", lastMsg
}

func tlsDialAddr(addrStr, serverName string, query []byte) ([]byte, string, string) {
	// serverName for SNI: host as extracted (including empty? For empty host, serverName=""? Go's tls with empty ServerName will use IP from addr? Actually Go will use hostname from addr if ServerName empty? But dog uses "" for SNI when host empty? However lookup already failed for empty host, so we wouldn't reach here. Good.
