func cgoResolve(host, portStr string, socktype int) ([]string, string) {
	chost := C.CString(host)
	defer C.free(unsafe.Pointer(chost))
	cport := C.CString(portStr)
	defer C.free(unsafe.Pointer(cport))
	var hints C.struct_addrinfo
	C.memset(unsafe.Pointer(&hints), 0, C.sizeof_struct_addrinfo)
	hints.ai_family = C.AF_UNSPEC
	if socktype == 1 {
		hints.ai_socktype = C.SOCK_DGRAM
	} else {
		hints.ai_socktype = C.SOCK_STREAM
	}
	var res *C.struct_addrinfo
	ret := C.getaddrinfo(chost, cport, &hints, &res)
	if ret != 0 {
		errStr := C.GoString(C.gai_strerror(ret))
		return nil, errStr
	}
	defer C.freeaddrinfo(res)
	var addrs []string
	for r := res; r != nil; r = r.ai_next {
		var ipStr string
		var port int
		if r.ai_family == C.AF_INET {
			sa := (*C.struct_sockaddr_in)(unsafe.Pointer(r.ai_addr))
			var buf [C.INET_ADDRSTRLEN]C.char
			C.inet_ntop(C.AF_INET, unsafe.Pointer(&sa.sin_addr), &buf[0], C.INET_ADDRSTRLEN)
			ipStr = C.GoString(&buf[0])
			port = int(C.ntohs(sa.sin_port))
		} else if r.ai_family == C.AF_INET6 {
			sa := (*C.struct_sockaddr_in6)(unsafe.Pointer(r.ai_addr))
			var buf [C.INET6_ADDRSTRLEN]C.char
			C.inet_ntop(C.AF_INET6, unsafe.Pointer(&sa.sin6_addr), &buf[0], C.INET6_ADDRSTRLEN)
			ipStr = C.GoString(&buf[0])
			port = int(C.ntohs(sa.sin6_port))
		} else {
			continue
		}
		if strings.Contains(ipStr, ":") {
			addrs = append(addrs, fmt.Sprintf("[%s]:%d", ipStr, port))
		} else {
			addrs = append(addrs, fmt.Sprintf("%s:%d", ipStr, port))
		}
	}
	if len(addrs) == 0 {
		return nil, "Name or service not known"
	}
	return addrs, ""
}

func formatOsError(errno syscall.Errno) string {
	msg := errno.Error()
	if len(msg) > 0 {
		msg = strings.ToUpper(msg[:1]) + msg[1:]
	}
	return fmt.Sprintf("%s (os error %d)", msg, int(errno))
}

func extractErrno(err error) (syscall.Errno, bool) {
	var errno syscall.Errno
	if errors.As(err, &errno) {
		return errno, true
	}
	return 0, false
}

func parsePortRust(portStr string) (uint16, string) {
	// Returns (port, errorKind) where errorKind is "" if ok, else "Empty", "InvalidDigit", "PosOverflow"
	if portStr == "" {
		return 0, "Empty"
	}
	s := portStr
	if strings.HasPrefix(s, "+") {
		s = s[1:]
		if s == "" {
			return 0, "InvalidDigit"
		}
	} else if strings.HasPrefix(s, "-") {
		return 0, "InvalidDigit"
	}
	// Check all digits
	for i := 0; i < len(s); i++ {
		if s[i] < '0' || s[i] > '9' {
			return 0, "InvalidDigit"
		}
	}
	// Parse value
	val := 0
	for i := 0; i < len(s); i++ {
		val = val*10 + int(s[i]-'0')
		if val > 65535 {
			return 0, "PosOverflow"
		}
	}
	return uint16(val), ""
}

