	for {
		n, err := conn.Read(tmp)
		if err != nil {
			if errno, ok := extractErrno(err); ok {
				return nil, "network", formatOsError(errno)
			}
			return nil, "network", err.Error()
		}
		if n == 0 {
			continue
		}
		headerBuf = append(headerBuf, tmp[0])
		if len(headerBuf) >= 4 && string(headerBuf[len(headerBuf)-4:]) == "\r\n\r\n" {
			break
		}
		if len(headerBuf) > 8192 {
			return nil, "network", "invalid http response"
		}
	}
	headerStr := string(headerBuf)
	lines := strings.Split(headerStr, "\r\n")
	if len(lines) == 0 {
		return nil, "network", "invalid http response"
	}
	statusLine := lines[0]
