		return nil, "network", fmt.Sprintf("https server returned status %s", statusCode)
	}
	// Parse headers for Content-Length
	contentLen := -1
	chunked := false
	for _, line := range lines[1:] {
		if line == "" {
			continue
		}
		colon := strings.Index(line, ":")
		if colon < 0 {
			continue
		}
		name := strings.ToLower(strings.TrimSpace(line[:colon]))
		value := strings.TrimSpace(line[colon+1:])
		if name == "content-length" {
			var l int
			fmt.Sscanf(value, "%d", &l)
			contentLen = l
		} else if name == "transfer-encoding" && strings.Contains(strings.ToLower(value), "chunked") {
			chunked = true
		}
	}
	if chunked {
		// Read chunked body
		var body []byte
		for {
			// Read chunk size line
			var lineBuf []byte
			for {
				n, err := conn.Read(tmp)
				if err != nil {
					if errno, ok := extractErrno(err); ok {
						return nil, "network", formatOsError(errno)
					}
					return nil, "network", err.Error()
				}
				if n == 0 {
					continue
				}
				lineBuf = append(lineBuf, tmp[0])
				if len(lineBuf) >= 2 && string(lineBuf[len(lineBuf)-2:]) == "\r\n" {
					break
				}
			}
			lineStr := strings.TrimSpace(string(lineBuf))
			// Chunk size may have extensions after ';'
			if semi := strings.Index(lineStr, ";"); semi >= 0 {
				lineStr = lineStr[:semi]
			}
			var chunkSize int
			fmt.Sscanf(lineStr, "%x", &chunkSize)
			if chunkSize == 0 {
				// Read trailing \r\n and break
				trailer := make([]byte, 2)
				io.ReadFull(conn, trailer)
				break
			}
			chunk := make([]byte, chunkSize)
			_, err := io.ReadFull(conn, chunk)
			if err != nil {
				if errno, ok := extractErrno(err); ok {
					return nil, "network", formatOsError(errno)
				}
				return nil, "network", err.Error()
			}
			body = append(body, chunk...)
			// Read trailing \r\n
			trailer := make([]byte, 2)
			io.ReadFull(conn, trailer)
		}
		return body, "", ""
	} else if contentLen >= 0 {
		body := make([]byte, contentLen)
		_, err := io.ReadFull(conn, body)
		if err != nil {
			if errno, ok := extractErrno(err); ok {
				return nil, "network", formatOsError(errno)
			}
			return nil, "network", err.Error()
		}
		return body, "", ""
	} else {
		// No content-length, read until EOF (connection close)
		var body []byte
		buf := make([]byte, 4096)
		for {
			n, err := conn.Read(buf)
			if n > 0 {
				body = append(body, buf[:n]...)
			}
