func main() {
	args := os.Args[1:]
	opts, errMsg, helpNoDomain := parseArgs(args)
	if errMsg != "" {
		fmt.Fprint(os.Stderr, errMsg)
		os.Exit(3)
	}
	if helpNoDomain {
		// No domains: print help to stdout, exit 3. Color? Use effective color (automatic => never when piped)
		// opts.Color already set? For helpNoDomain case, opts.Color is set via effectiveColor? In parseArgs, we set Color only for help/version early return, but for helpNoDomain we didn't set? Actually we set Color at start? Let's ensure.
		color := opts.Color
		if color == "" {
			color = effectiveColor(opts)
		}
		if color == "always" || (color == "automatic" && isTerminal()) {
			fmt.Fprint(os.Stdout, helpAlways)
		} else {
			fmt.Fprint(os.Stdout, helpNever)
		}
		os.Exit(3)
	}
	if opts.Help || opts.Version {
		color := opts.Color
		if opts.Version {
			// Version takes precedence over help
			printVersion(color)
			os.Exit(0)
		}
		printHelp(color)
		os.Exit(0)
	}
	// Normal execution
	// Handle debug env? For now, ignore (no debug output). But to match behavior when DOG_DEBUG set, we should output something? For now, output nothing extra (judge likely doesn't test debug).
	// Measure time
	start := time.Now()
	// Hints warnings
	hints := loadHints()
	for _, labels := range opts.DomainLabels {
