			key = ""
		} else {
			key = strings.Join(labels, ".")
		}
		if _, ok := hints[strings.ToLower(key)]; ok && key != "" {
			fmt.Fprintf(os.Stderr, "warning: domain '%s' also exists in hosts file\n", domainStr)
		}
	}
	// Get system nameserver if needed
	var systemNS string
	needSystem := len(opts.Nameservers) == 0
	if needSystem {
		ns, errMsg := getSystemNameserver()
		if errMsg != "" {
			// Exit 4. What message? Guess: "Error: ..." to stderr?
			// For now, print to stderr and exit 4. Message format unknown.
			// Let's print as "dog: Failed to obtain system nameserver information\n"? Or "Error [system]: ..."?
			// To be safe, print number? We'll print "dog: Failed to get system nameserver: <msg>\n" ?
