			// We'll print "Error: <msg>\n" ?
			// For now, use: fmt.Fprintf(os.Stderr, "Error: %s\n", errMsg)
			fmt.Fprintf(os.Stderr, "dog: Failed to get system nameserver information\n")
			os.Exit(4)
		}
		systemNS = ns
		_ = systemNS
	}
	// Build list of nameservers to query: if explicit, use those; else system
	var nsList []string
	if len(opts.Nameservers) > 0 {
		nsList = opts.Nameservers
	} else {
		nsList = []string{systemNS}
	}
	// Execute queries in order: domains -> types -> classes -> nameservers -> transports
	var responses []*Response
	var errors []QueryError
	// For TXID: if set, use fixed; else random per query
	for _, domainLabels := range opts.DomainLabels {
		for _, qtype := range opts.Types {
			for _, qclass := range opts.Classes {
				for _, ns := range nsList {
					for _, transp := range opts.Transports {
						var txid uint16
						if opts.TxidSet {
							txid = opts.Txid
						} else {
							txid = randomTxid()
						}
						queryPkt := buildQuery(domainLabels, qtype, qclass, txid, opts.Edns, opts.TweaksAA, opts.TweaksAD, opts.TweaksCD, opts.Bufsize)
						if transp == "Automatic" {
							// UDP with TCP fallback on TC
							respBytes, phase, msg := doUDPQuery(ns, queryPkt)
							if phase != "" {
								errors = append(errors, QueryError{Phase: phase, Message: msg})
								continue
							}
							resp, parseErr := parseResponse(respBytes)
							if parseErr != "" {
								errors = append(errors, QueryError{Phase: "protocol", Message: "Malformed packet: " + parseErr})
								continue
							}
							if resp.TC {
								// Retry via TCP with same query (same TXID, same packet? Actually same query bytes? Yes, same TXID)
								respBytes2, phase2, msg2 := doTCPQuery(ns, queryPkt)
								if phase2 != "" {
									errors = append(errors, QueryError{Phase: phase2, Message: msg2})
									continue
								}
								resp2, parseErr2 := parseResponse(respBytes2)
								if parseErr2 != "" {
									errors = append(errors, QueryError{Phase: "protocol", Message: "Malformed packet: " + parseErr2})
									continue
								}
								responses = append(responses, resp2)
							} else {
								responses = append(responses, resp)
							}
						} else if transp == "UDP" {
							respBytes, phase, msg := doUDPQuery(ns, queryPkt)
							if phase != "" {
								errors = append(errors, QueryError{Phase: phase, Message: msg})
								continue
							}
							resp, parseErr := parseResponse(respBytes)
							if parseErr != "" {
								errors = append(errors, QueryError{Phase: "protocol", Message: "Malformed packet: " + parseErr})
								continue
							}
							responses = append(responses, resp)
						} else if transp == "TCP" {
							respBytes, phase, msg := doTCPQuery(ns, queryPkt)
							if phase != "" {
								errors = append(errors, QueryError{Phase: phase, Message: msg})
								continue
							}
							resp, parseErr := parseResponse(respBytes)
							if parseErr != "" {
								errors = append(errors, QueryError{Phase: "protocol", Message: "Malformed packet: " + parseErr})
								continue
							}
							responses = append(responses, resp)
						} else if transp == "TLS" {
							respBytes, phase, msg := doTLSQuery(ns, queryPkt)
							if phase != "" {
								errors = append(errors, QueryError{Phase: phase, Message: msg})
								continue
							}
							resp, parseErr := parseResponse(respBytes)
							if parseErr != "" {
								errors = append(errors, QueryError{Phase: "protocol", Message: "Malformed packet: " + parseErr})
								continue
							}
							responses = append(responses, resp)
						} else if transp == "HTTPS" {
							respBytes, phase, msg := doHTTPSQuery(ns, queryPkt)
							if phase != "" {
								errors = append(errors, QueryError{Phase: phase, Message: msg})
								continue
							}
							resp, parseErr := parseResponse(respBytes)
							if parseErr != "" {
								errors = append(errors, QueryError{Phase: "protocol", Message: "Malformed packet: " + parseErr})
								continue
							}
							responses = append(responses, resp)
						}
					}
				}
			}
		}
	}
	elapsed := time.Since(start)
	// Output
	useColor := false
	if opts.Color == "always" {
		useColor = true
	} else if opts.Color == "automatic" && isTerminal() {
		useColor = true
	}
	// Short takes precedence over JSON? Earlier -1 -J gave Short. Our opts.Short and opts.JSON both true in that case. Short wins.
	isShort := opts.Short
	isJSON := opts.JSON && !isShort
	if isJSON {
		outputJSON(responses, errors, elapsed, opts.MeasureTime)
	} else if isShort {
		outputShort(responses, errors, opts)
	} else {
		outputText(responses, errors, elapsed, opts, useColor)
	}
	// Exit code logic
	hasError := len(errors) > 0
	if isShort {
		// Count total answers
		totalAnswers := 0
		for _, r := range responses {
			totalAnswers += len(r.Answers)
