			os.Exit(2)
		} else {
			if hasError {
				os.Exit(1)
			} else {
				os.Exit(0)
			}
		}
	} else {
		if hasError {
			os.Exit(1)
		} else {
			os.Exit(0)
		}
	}
}

func randomTxid() uint16 {
	var b [2]byte
	_, err := rand.Read(b[:])
	if err != nil {
		// fallback to time-based?
		return uint16(time.Now().UnixNano() & 0xFFFF)
	}
	return binary.BigEndian.Uint16(b[:])
}

func loadHints() map[string]bool {
	m := make(map[string]bool)
	data, err := os.ReadFile("/etc/hosts")
	if err != nil {
		return m
	}
	lines := strings.Split(string(data), "\n")
	for _, line := range lines {
		// Strip comments after '#'
		if idx := strings.Index(line, "#"); idx >= 0 {
			line = line[:idx]
		}
		fields := strings.Fields(line)
		if len(fields) < 2 {
			continue
		}
		// First is IP, rest are hostnames
		for _, h := range fields[1:] {
			m[strings.ToLower(h)] = true
		}
	}
	return m
}

// JSON output structures with ordered fields
type jsonQuery struct {
	Name  string      `json:"name"`
	Class interface{} `json:"class"`
	Type  interface{} `json:"type"`
}

type jsonRecord struct {
	Name  string      `json:"name"`
	Class interface{} `json:"class,omitempty"`
	TTL   *uint32     `json:"ttl,omitempty"`
	Type  interface{} `json:"type"`
	Data  interface{} `json:"data"`
}

type jsonResponse struct {
	Queries     []jsonQuery  `json:"queries"`
	Answers     []jsonRecord `json:"answers"`
	Authorities []jsonRecord `json:"authorities"`
	Additionals []jsonRecord `json:"additionals"`
}

type jsonOutput struct {
	Responses []jsonResponse `json:"responses"`
	Duration  *jsonDuration  `json:"duration,omitempty"`
}

type jsonDuration struct {
	Secs   int64 `json:"secs"`
	Millis int64 `json:"millis"`
}

func outputJSON(responses []*Response, errors []QueryError, elapsed time.Duration, measureTime bool) {
	// Build responses
	var jresps []jsonResponse
	if responses == nil {
		jresps = []jsonResponse{}
		// Actually for JSON with no responses, output {"responses":[]} (empty array, not null)
		// Ensure non-nil slice marshals as [].
	} else {
		for _, r := range responses {
			jr := jsonResponse{
				Queries:     []jsonQuery{},
				Answers:     []jsonRecord{},
				Authorities: []jsonRecord{},
				Additionals: []jsonRecord{},
			}
			for _, q := range r.Questions {
				var classVal interface{}
				if name, ok := classCodeToName(q.Class); ok {
					classVal = name
				} else {
					classVal = q.Class
				}
				var typeVal interface{}
				if name, ok := typeCodeToName(q.Type); ok {
					typeVal = name
				} else {
					typeVal = q.Type
				}
				jr.Queries = append(jr.Queries, jsonQuery{Name: q.Name, Class: classVal, Type: typeVal})
			}
			for _, a := range r.Answers {
				// Filter OPT if edns != show? Need opts.Edns. Pass via global? For now, assume filtering done by caller? Actually outputJSON needs edns setting to filter OPT.
				// We'll handle filtering in caller? For simplicity, filter here based on... Need opts. Change signature to include opts.
				_ = a
			}
			jresps = append(jresps, jr)
		}
	}
	_ = jresps
	_ = json.Marshal
}

func outputShort(responses []*Response, errors []QueryError, opts *Options) {
}

func outputText(responses []*Response, errors []QueryError, elapsed time.Duration, opts *Options, useColor bool) {
}
